import { useQuery } from '@tanstack/react-query';
import type { QueuePublishedSelectionPlanV4 } from '../../../shared/queueSelectionPlanV4';
import { getQueueSelectionOptionsV4 } from '../api/queueSelectionsV4';
import type { CounterCardPlan } from './queueCounterCard';
import { Badge } from './components/ui/badge';
import { useQueueNamedAvailability, type NamedAvailabilityScope } from './useQueueNamedAvailability';
import { requestPreviewSelections, requestPreviewAvailability, previewAvailabilityPresentation } from './requestPreviewAvailability';
/** Child-owned reads keep the parent dialog/controller hook order and its command owner stable. */
export function RequestPreviewResources({plan,scope}:{plan:CounterCardPlan;scope:NamedAvailabilityScope}){
 const v4=plan.contractVersion===4?plan as QueuePublishedSelectionPlanV4:undefined;
 const options=useQuery({queryKey:['queue-request-preview-options',scope.token,scope.tenant,scope.location],enabled:Boolean(v4),retry:false,refetchInterval:15000,queryFn:({signal})=>getQueueSelectionOptionsV4(scope.token,scope.tenant,scope.location,signal)});
 const selections=v4?requestPreviewSelections(v4):[];
 const availability=useQueueNamedAvailability({...scope,draftId:v4?.draftId},Boolean(v4&&options.data&&!options.isError),options.data?.catalogRevision||'',selections);
 const badge=(serviceId:string,selectionId:string,memberId:string|null)=>{const status=previewAvailabilityPresentation(requestPreviewAvailability(availability.response,serviceId,selectionId,memberId),Boolean(v4&&!options.isError&&(options.isPending||availability.checking)));return <Badge variant={status.variant}>{status.label}</Badge>;};
 return <div className="queue-request-details-list queue-request-preview-resources"><p className="ops-muted">Availability is provisional until Call.</p>{'serviceSelections' in plan?plan.serviceSelections.map((service,index)=><section className="queue-request-detail-service" key={service.serviceSelectionId}><h3>{service.serviceName||`Service ${index+1}`}</h3><ul>{service.resources.map((resource,resourceIndex)=><li key={resource.resourceSelectionId}><div className="queue-request-detail-row"><span>{resource.resourceMemberName||`Resource ${resourceIndex+1}`}</span>{badge(service.serviceId,resource.resourceSelectionId,resource.resourceMemberId)}<span>· {resource.quantity} unit(s) · {resource.durationMinutes} minutes</span></div>{resource.extras.length?<ul className="queue-request-detail-extras">{resource.extras.map(extra=><li key={extra.extraSelectionId}><span>{extra.serviceName} · {extra.quantity} unit(s) · {extra.durationMinutes} minutes</span>{'resourceMemberIds' in extra&&extra.resourceMemberIds?.length?extra.resourceMemberIds.map(memberId=><span key={memberId}>{'resourceMembers' in extra?extra.resourceMembers?.find(member=>member.id===memberId)?.name||'Selected extra resource':'Selected extra resource'} {badge(extra.serviceId,extra.extraSelectionId,memberId)}</span>):badge(extra.serviceId,extra.extraSelectionId,null)}</li>)}</ul>:null}</li>)}</ul></section>):plan.lines.map(line=><section className="queue-request-detail-service" key={line.lineId}><h3>{line.serviceName}</h3><p>{line.quantity} unit(s) · {line.durationMinutes} minutes</p>{line.requirements.length?<p className="ops-muted">{line.requirements.reduce((total,requirement)=>total+requirement.totalUnits,0)} resource unit(s) required</p>:null}<Badge variant="secondary">Availability not confirmed</Badge></section>)}</div>;
}
